import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative, resolve, sep } from 'node:path';
import { moduleManifestSchema } from '@app/module-sdk';

/**
 * Static checks for one module folder: the contract every module (scaffolded, written by hand,
 * generated by an AI agent or added from the catalog) must meet before it goes into a build.
 * Returns problems as readable lines; an empty list means the folder passes.
 */

const CODE = new Set(['.ts', '.tsx']);
const TEXT = new Set(['.ts', '.tsx', '.json', '.md', '.hbs', '.txt', '.css']);
const SKIP = new Set(['node_modules', '.git', 'dist']);

function* files(dir: string): Generator<string> {
  if (!existsSync(dir)) return;
  for (const entry of readdirSync(dir)) {
    if (SKIP.has(entry)) continue;
    const p = join(dir, entry);
    if (statSync(p).isDirectory()) yield* files(p);
    else yield p;
  }
}

const ext = (p: string) => p.slice(p.lastIndexOf('.'));

export function brandTerms(root: string): string[] {
  const f = join(root, 'brand-denylist.txt');
  if (!existsSync(f)) return [];
  return readFileSync(f, 'utf8')
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#'));
}

/** Brand terms found in a folder (`relative path: "term"`). */
export function brandHits(root: string, dir: string, allowed: string[] = []): string[] {
  const deny = brandTerms(root);
  const hits: string[] = [];
  for (const f of files(dir)) {
    const rel = relative(root, f).split(sep).join('/');
    if (!TEXT.has(ext(f)) || allowed.includes(rel)) continue;
    const text = readFileSync(f, 'utf8').toLowerCase();
    for (const word of deny) if (text.includes(word.toLowerCase())) hits.push(`${rel}: "${word}"`);
  }
  return hits;
}

export interface CheckOptions {
  /** The key the folder must declare (the folder name by default). */
  key?: string;
  /** Module keys available to depend on (folders in `modules/` by default). */
  knownModules?: string[];
}

/** Data files allowed to name other companies (see AGENTS.md: the assistant's provider list). */
export const BRAND_ALLOWED = ['modules/assistant/providers.json'];

export function checkModuleFolder(root: string, dir: string, opts: CheckOptions = {}): string[] {
  const problems: string[] = [];
  const folder = resolve(dir);
  const manifestPath = join(folder, 'manifest.json');
  if (!existsSync(manifestPath)) return ['manifest.json is missing'];

  let raw: unknown;
  try {
    raw = JSON.parse(readFileSync(manifestPath, 'utf8'));
  } catch {
    return ['manifest.json is not valid JSON'];
  }
  const parsed = moduleManifestSchema.safeParse(raw);
  if (!parsed.success) {
    for (const issue of parsed.error.issues)
      problems.push(`manifest.json ${issue.path.join('.') || '(root)'}: ${issue.message}`);
    return problems;
  }
  const m = parsed.data;
  const key = opts.key ?? folder.split(sep).pop()!;
  if (m.key !== key) problems.push(`manifest key "${m.key}" does not match the folder "${key}"`);
  if (m.key === 'custom') problems.push('the key "custom" is reserved for admin-defined objects');

  const known =
    opts.knownModules ?? (existsSync(join(root, 'modules')) ? readdirSync(join(root, 'modules')) : []);
  for (const dep of m.depends_on)
    if (!known.includes(dep)) problems.push(`depends on "${dep}", which is not in modules/`);

  const helpDir = join(folder, 'help');
  if (!existsSync(helpDir) || !readdirSync(helpDir).some((f) => f.endsWith('.md')))
    problems.push('help/<key>.md is missing: every module needs a help article');

  if (!existsSync(join(folder, 'api', 'index.ts')) && !existsSync(join(folder, 'web', 'index.tsx')))
    problems.push('neither api/index.ts nor web/index.tsx exists');

  const prefix = `m_${m.key.replace(/-/g, '_')}_`;
  for (const f of files(folder)) {
    if (!CODE.has(ext(f))) continue;
    const rel = relative(folder, f).split(sep).join('/');
    const text = readFileSync(f, 'utf8');
    const side = rel.startsWith('web/') ? 'web' : 'api';
    for (const [, spec] of text.matchAll(/(?:from|import)\s*\(?\s*'([^']+)'/g)) {
      if (!spec) continue;
      if (spec.startsWith('.')) {
        const target = resolve(join(f, '..'), spec);
        const modulesDir = resolve(folder, '..');
        const other = target.startsWith(modulesDir + sep) ? relative(modulesDir, target).split(sep)[0] : null;
        // Another module's exports are fine when that module ships in the same build.
        if (target.startsWith(folder + sep) || target === folder) continue;
        if (!other || !known.includes(other))
          problems.push(`${rel}: imports "${spec}" from outside the module`);
      } else if (spec.startsWith('@app/api') && spec !== '@app/api/module-api') {
        problems.push(`${rel}: imports "${spec}"; API code may only import "@app/api/module-api"`);
      } else if (side === 'api' && spec.startsWith('@/')) {
        problems.push(`${rel}: API code imports web code "${spec}"`);
      } else if (side === 'web' && spec.startsWith('@app/api')) {
        problems.push(`${rel}: web code imports API code "${spec}"`);
      } else if (/^(node:)?(child_process|vm|worker_threads|cluster)$/.test(spec)) {
        problems.push(`${rel}: imports "${spec}", which modules may not use`);
      }
    }
    if (/\beval\s*\(|new Function\s*\(/.test(text))
      problems.push(`${rel}: runs generated code (eval or new Function)`);
    if (rel.startsWith('api/migrations/')) {
      for (const [, table] of text.matchAll(
        /\.(?:createTable|alterTable|dropTable|dropTableIfExists|renameTable|table)\(\s*'([^']+)'/g,
      ))
        if (table && !table.startsWith(prefix))
          problems.push(`${rel}: table "${table}" must start with "${prefix}"`);
    }
  }

  for (const hit of brandHits(root, folder, BRAND_ALLOWED)) problems.push(`brand name in ${hit}`);
  return problems;
}
